const DefaultStatus schema.BundleCatalogStatus = "draft"

// StatusValidator is a validator for the "status" field enum values. It is called by the builders before save.
func StatusValidator(s schema.BundleCatalogStatus) error {
	switch s {
	case "draft", "submitted", "published", "suspended", "removed":
		return nil
	default:
		return fmt.Errorf("bundles: invalid enum value for status field: %q", s)
	}
}

const DefaultActiveDeliveryMode schema.BundleDeliveryMode = "none"

// ActiveDeliveryModeValidator is a validator for the "activeDeliveryMode" field enum values. It is called by the builders before save.
